import { useMemo, useState } from "react";
import { Pressable, ScrollView, StyleSheet, Text, View } from "react-native";
import Svg, { Line, Polygon, Rect, Text as SvgText } from "react-native-svg";
import { radii, spacing, useKeatingTheme } from "@/constants/theme";
import { parseMermaidFlowchart } from "@/lib/mermaid-native";

const NODE_WIDTH = 132;
const NODE_HEIGHT = 48;

export function MermaidDiagram({ source }: { source: string }) {
  const theme = useKeatingTheme();
  const styles = createStyles(theme);
  const graph = useMemo(() => parseMermaidFlowchart(source), [source]);
  const [sourceOpen, setSourceOpen] = useState(false);
  if (!graph) return <DiagramFallback source={source} reason="This Mermaid diagram uses syntax the native renderer does not support yet." />;
  const levels = new Map<number, typeof graph.nodes>();
  graph.nodes.forEach((node) => levels.set(node.level, [...(levels.get(node.level) ?? []), node]));
  const maxAcross = Math.max(...[...levels.values()].map((nodes) => nodes.length));
  const maxLevel = Math.max(...graph.nodes.map((node) => node.level));
  const width = graph.direction === "LR" ? (maxLevel + 1) * 180 : Math.max(320, maxAcross * 156);
  const height = graph.direction === "LR" ? Math.max(132, maxAcross * 84) : (maxLevel + 1) * 92;
  const positions = new Map<string, { x: number; y: number }>();
  for (const [level, nodes] of levels) {
    nodes.forEach((node, index) => {
      const x = graph.direction === "LR" ? 24 + level * 180 : (width - nodes.length * 156) / 2 + index * 156 + 12;
      const y = graph.direction === "LR" ? 20 + index * 84 : 20 + level * 92;
      positions.set(node.id, { x, y });
    });
  }
  return (
    <View style={styles.frame}>
      <ScrollView horizontal showsHorizontalScrollIndicator contentContainerStyle={styles.scroller}>
        <Svg accessibilityRole="image" accessibilityLabel={`Flowchart with ${graph.nodes.length} nodes and ${graph.edges.length} connections`} width={width} height={height}>
          {graph.edges.map((edge, index) => {
            const from = positions.get(edge.from)!;
            const to = positions.get(edge.to)!;
            const startX = graph.direction === "LR" ? from.x + NODE_WIDTH : from.x + NODE_WIDTH / 2;
            const startY = graph.direction === "LR" ? from.y + NODE_HEIGHT / 2 : from.y + NODE_HEIGHT;
            const endX = graph.direction === "LR" ? to.x : to.x + NODE_WIDTH / 2;
            const endY = graph.direction === "LR" ? to.y + NODE_HEIGHT / 2 : to.y;
            const arrow = graph.direction === "LR"
              ? `${endX},${endY} ${endX - 8},${endY - 5} ${endX - 8},${endY + 5}`
              : `${endX},${endY} ${endX - 5},${endY - 8} ${endX + 5},${endY - 8}`;
            return <View key={`${edge.from}-${edge.to}-${index}`}>
              <Line x1={startX} y1={startY} x2={endX} y2={endY} stroke={theme.colors.primaryText} strokeWidth={2} />
              <Polygon points={arrow} fill={theme.colors.primaryText} />
              {edge.label ? <SvgText x={(startX + endX) / 2} y={(startY + endY) / 2 - 5} fill={theme.colors.textMuted} fontSize={11} textAnchor="middle">{truncate(edge.label, 18)}</SvgText> : null}
            </View>;
          })}
          {graph.nodes.map((node) => {
            const position = positions.get(node.id)!;
            return <View key={node.id}>
              <Rect x={position.x} y={position.y} width={NODE_WIDTH} height={NODE_HEIGHT} rx={8} fill={theme.colors.surfaceRaised} stroke={theme.colors.borderStrong} strokeWidth={1} />
