import { marked, type Token, type Tokens, type TokensList } from "marked";

export const MAX_MARKDOWN_LENGTH = 65_536;

export function parseMarkdownDocument(content: string): TokensList {
  const bounded = content.length > MAX_MARKDOWN_LENGTH ? `${content.slice(0, MAX_MARKDOWN_LENGTH)}\n\n[Message truncated]` : content;
  return marked.lexer(bounded, { gfm: true, breaks: true });
}

export function isMermaidCode(token: Token): token is Tokens.Code {
  return token.type === "code" && /^mermaid(?:\s|$)/i.test((token as Tokens.Code).lang?.trim() ?? "");
}

export function safeMarkdownUri(value: string, kind: "link" | "image"): URL | null {
  try {
    const url = new URL(value);
    if (url.username || url.password) return null;
    if (url.protocol === "https:") return url;
    if (kind === "link" && url.protocol === "http:" && ["localhost", "127.0.0.1", "[::1]"].includes(url.hostname)) return url;
    if (kind === "link" && url.protocol === "mailto:" && !url.search && !url.hash) return url;
    return null;
  } catch {
    return null;
  }
}

export function markdownTokenTypes(tokens: readonly Token[]): string[] {
  const types: string[] = [];
  const visit = (entries: readonly Token[]) => {
    for (const token of entries) {
      types.push(token.type);
      if ("tokens" in token && Array.isArray(token.tokens)) visit(token.tokens);
      if (token.type === "list") (token as Tokens.List).items.forEach((item: Tokens.ListItem) => visit(item.tokens));
      if (token.type === "table") {
        (token as Tokens.Table).header.forEach((cell: Tokens.TableCell) => visit(cell.tokens));
        (token as Tokens.Table).rows.flat().forEach((cell: Tokens.TableCell) => visit(cell.tokens));
      }
      if (token.type === "blockquote") visit((token as Tokens.Blockquote).tokens);
    }
  };
  visit(tokens);
  return types;
}
export interface MermaidNode { id: string; label: string; level: number }
export interface MermaidEdge { from: string; to: string; label?: string }
export interface MermaidFlowchart { direction: "TD" | "LR"; nodes: MermaidNode[]; edges: MermaidEdge[] }

const NODE = String.raw`([A-Za-z0-9_.-]+)(?:\[([^\]]*)\]|\(([^)]*)\)|\{([^}]*)\})?`;
const EDGE = new RegExp(`^\\s*${NODE}\\s*(?:-->|---|-.->|==>)\\s*(?:\\|([^|]+)\\|\\s*)?${NODE}\\s*$`);
const DECLARATION = new RegExp(`^\\s*${NODE}\\s*$`);

/** A bounded native renderer for the flowcharts Keating emits most often. */
export function parseMermaidFlowchart(source: string): MermaidFlowchart | null {
  if (source.length > 16_384) return null;
  const statements = source.split(/[;\n]+/).map((line) => line.trim()).filter(Boolean);
  const header = statements.shift()?.match(/^(?:graph|flowchart)\s+(TD|TB|LR|RL)$/i);
  if (!header) return null;
  const direction = /LR|RL/i.test(header[1]) ? "LR" : "TD";
  const labels = new Map<string, string>();
  const edges: MermaidEdge[] = [];
  const addNode = (id: string, ...possible: Array<string | undefined>) => labels.set(id, possible.find((value) => value?.trim())?.trim() ?? labels.get(id) ?? id);
  for (const statement of statements) {
    if (/^(?:classDef|class|style|linkStyle|click|subgraph|end)\b/i.test(statement)) return null;
    const edge = statement.match(EDGE);
    if (edge) {
      const [from, fromBox, fromRound, fromDiamond, edgeLabel, to, toBox, toRound, toDiamond] = edge.slice(1);
      addNode(from!, fromBox, fromRound, fromDiamond);
      addNode(to!, toBox, toRound, toDiamond);
      edges.push({ from: from!, to: to!, ...(edgeLabel?.trim() ? { label: edgeLabel.trim() } : {}) });
      continue;
    }
    const declaration = statement.match(DECLARATION);
    if (!declaration) return null;
    addNode(declaration[1]!, declaration[2], declaration[3], declaration[4]);
  }
  if (!labels.size || labels.size > 48 || edges.length > 96) return null;
  const levels = new Map([...labels.keys()].map((id) => [id, 0]));
  for (let pass = 0; pass < labels.size; pass += 1) {
    let changed = false;
    for (const edge of edges) {
      const next = Math.min(labels.size - 1, (levels.get(edge.from) ?? 0) + 1);
      if (next > (levels.get(edge.to) ?? 0)) { levels.set(edge.to, next); changed = true; }
    }
    if (!changed) break;
  }
  return {
    direction,
    nodes: [...labels].map(([id, label]) => ({ id, label, level: levels.get(id) ?? 0 })),
    edges,
  };
}
import { validateUiDocument, type UiDocument } from "@keating/learner-contracts";

export interface ExtractedUiDocuments {
  content: string;
  documents: UiDocument[];
  errors: string[];
}

const OPENING_FENCE = /^```(?:keating-ui|ui-document|openui-json|openui)(?:[ \t]+[^\n]*)?\n/gm;
const MAX_DOCUMENTS = 8;

/**
 * Compiles the JSON interchange form of Keating OpenUI into validated shared
 * documents. Browser OpenUI source is never evaluated on-device.
 */
export function extractUiDocuments(source: string): ExtractedUiDocuments {
  const documents: UiDocument[] = [];
  const errors: string[] = [];
  const text: string[] = [];
  let cursor = 0;
  OPENING_FENCE.lastIndex = 0;
  let match: RegExpExecArray | null;
  while ((match = OPENING_FENCE.exec(source)) !== null) {
    const bodyStart = OPENING_FENCE.lastIndex;
    const closingMatch = /^```[ \t]*$/m.exec(source.slice(bodyStart));
    if (!closingMatch) break;
    const bodyEnd = bodyStart + closingMatch.index;
    const fenceEnd = bodyEnd + closingMatch[0].length;
    const body = source.slice(bodyStart, bodyEnd).trim();
    text.push(source.slice(cursor, match.index));
    if (documents.length >= MAX_DOCUMENTS) {
      errors.push("This response contains more interactive documents than mobile can safely render.");
    } else {
      try {
        const candidate = JSON.parse(body) as unknown;
        if (!validateUiDocument(candidate)) throw new Error("document schema is invalid");
        if (!candidate.supportedSurfaces.includes("mobile")) {
          errors.push(`Interactive document ${candidate.id} does not declare mobile support.`);
        } else {
          documents.push(candidate);
        }
      } catch (error) {
        errors.push(error instanceof Error
          ? `Interactive document could not be rendered: ${error.message}.`
          : "Interactive document could not be rendered.");
      }
    }
    cursor = fenceEnd;
    if (source[cursor] === "\n") cursor += 1;
    OPENING_FENCE.lastIndex = cursor;
  }
  text.push(source.slice(cursor));
  return { content: text.join("").trim(), documents, errors };
}

/** Prevent partially streamed JSON from flashing as a code block. */
export function hideUnclosedUiDocumentFence(source: string): string {
  OPENING_FENCE.lastIndex = 0;
  let match: RegExpExecArray | null;
  let lastUnclosed = -1;
  while ((match = OPENING_FENCE.exec(source)) !== null) {
    const closing = /^```[ \t]*$/m.exec(source.slice(OPENING_FENCE.lastIndex));
    if (!closing) {
      lastUnclosed = match.index;
      break;
    }
    OPENING_FENCE.lastIndex += closing.index + closing[0].length;
  }
  return lastUnclosed < 0 ? source : source.slice(0, lastUnclosed).trimEnd();
}
import {
  type PortableLearnerData,
  type UiAction,
  type UiDocument,
