 18	interface StoredRow {
 19	  kind: string;
 20	  id: string;
 21	  sort_timestamp: string;
 22	  payload_json: string;
 23	}
 24	
 25	interface StoredPriorityRow {
 26	  id: string;
 27	  target_type: "deck" | "goal" | "topic" | "verification";
 28	  target_id: string;
 29	  updated_at: string;
 30	  payload_json: string;
 31	}
