 33	class MemoryDatabase implements AsyncSqlDatabase {
 34	  rows = new Map<string, StoredRow>();
 35	  profile: string | null = null;
 36	  priorities = new Map<string, StoredPriorityRow>();
 37	  meta = new Map<string, string>();
 38	  localAttachments = new Map<string, { messageId: string; attachmentId: string; uri: string }>();
 39	  uiActionJournals = new Map<string, { updated_at: string; payload_json: string }>();
 40	  closeCalls = 0;
 41	
 42	  async execAsync(_source: string): Promise<void> {}
 43	
 44	  async runAsync(source: string, ...params: SqlBindValue[]): Promise<{ changes: number; lastInsertRowId: number }> {
 45	    if (source.startsWith("DELETE FROM learner_records")) this.rows.clear();
 46	    else if (source.startsWith("DELETE FROM learner_profile")) this.profile = null;
 47	    else if (source.startsWith("DELETE FROM study_priorities")) this.priorities.clear();
 48	    else if (source.startsWith("DELETE FROM repository_meta")) this.meta.delete(String(params[0]));
 49	    else if (source.startsWith("DELETE FROM local_message_attachments")) this.localAttachments.clear();
 50	    else if (source.startsWith("DELETE FROM ui_action_journals")) this.uiActionJournals.clear();
 51	    else if (source.startsWith("INSERT INTO learner_records")) {
 52	      const [kind, id, sortTimestamp, payload] = params.map(String);
 53	      const key = `${kind}:${id}`;
 54	      if (this.rows.has(key)) throw new Error("UNIQUE constraint failed: learner_records.kind, learner_records.id");
 55	      this.rows.set(key, { kind, id, sort_timestamp: sortTimestamp, payload_json: payload });
 56	    } else if (source.startsWith("INSERT INTO learner_profile")) {
 57	      this.profile = String(params[0]);
 58	    } else if (source.startsWith("INSERT INTO study_priorities")) {
 59	      const [id, targetType, targetId, updatedAt, payload] = params.map(String);
 60	      if (this.priorities.has(id)) throw new Error("UNIQUE constraint failed: study_priorities.id");
 61	      if ([...this.priorities.values()].some((row) => row.target_type === targetType && row.target_id === targetId)) {
 62	        throw new Error("UNIQUE constraint failed: study_priorities.target_type, study_priorities.target_id");
 63	      }
 64	      this.priorities.set(id, {
 65	        id,
 66	        target_type: targetType as StoredPriorityRow["target_type"],
 67	        target_id: targetId,
 68	        updated_at: updatedAt,
 69	        payload_json: payload,
 70	      });
 71	    } else if (source.startsWith("INSERT INTO repository_meta")) {
 72	      this.meta.set(String(params[0]), String(params[1]));
 73	    } else if (source.startsWith("INSERT INTO local_message_attachments")) {
 74	      const [messageId, attachmentId, uri] = params.map(String);
 75	      this.localAttachments.set(`${messageId}:${attachmentId}`, { messageId, attachmentId, uri });
 76	    } else if (source.startsWith("INSERT INTO ui_action_journals")) {
 77	      const [documentId, updatedAt, payload] = params.map(String);
 78	      this.uiActionJournals.set(documentId, { updated_at: updatedAt, payload_json: payload });
 79	    }
 80	    return { changes: 1, lastInsertRowId: 1 };
 81	  }
 82	
 83	  async getFirstAsync<T>(source: string, ...params: SqlBindValue[]): Promise<T | null> {
 84	    if (source.includes("FROM learner_profile") && this.profile !== null) {
 85	      return { payload_json: this.profile } as T;
 86	    }
 87	    if (source.includes("FROM repository_meta")) {
 88	      const value = this.meta.get(String(params[0] ?? "portable_generated_at"));
 89	      return value === undefined ? null : { value } as T;
 90	    }
 91	    if (source.includes("FROM ui_action_journals")) {
 92	      const row = this.uiActionJournals.get(String(params[0]));
 93	      return row ? { payload_json: row.payload_json } as T : null;
 94	    }
 95	    return null;
 96	  }
 97	
 98	  async getAllAsync<T>(source: string): Promise<T[]> {
 99	    if (source.includes("FROM study_priorities")) {
100	      return [...this.priorities.values()]
101	        .sort((left, right) => left.updated_at.localeCompare(right.updated_at)
102	          || left.target_type.localeCompare(right.target_type)
103	          || left.target_id.localeCompare(right.target_id)) as T[];
104	    }
105	    if (source.includes("FROM local_message_attachments")) {
106	      return [...this.localAttachments.values()] as T[];
107	    }
108	    if (!source.includes("FROM learner_records")) return [];
109	    return [...this.rows.values()]
110	      .sort((left, right) => left.kind.localeCompare(right.kind)
111	        || left.sort_timestamp.localeCompare(right.sort_timestamp)
112	        || left.id.localeCompare(right.id)) as T[];
113	  }
114	
115	  async withExclusiveTransactionAsync(task: (transaction: AsyncSqlExecutor) => Promise<void>): Promise<void> {
116	    const previousRows = this.rows;
117	    const previousProfile = this.profile;
118	    const previousPriorities = this.priorities;
119	    const previousMeta = this.meta;
120	    const previousLocalAttachments = this.localAttachments;
121	    const previousUiActionJournals = this.uiActionJournals;
122	    this.rows = new Map([...previousRows].map(([key, value]) => [key, { ...value }]));
123	    this.priorities = new Map([...previousPriorities].map(([key, value]) => [key, { ...value }]));
124	    this.meta = new Map(previousMeta);
125	    this.localAttachments = new Map(previousLocalAttachments);
126	    this.uiActionJournals = new Map([...previousUiActionJournals].map(([key, value]) => [key, { ...value }]));
127	    try {
128	      await task(this);
129	    } catch (error) {
130	      this.rows = previousRows;
131	      this.profile = previousProfile;
132	      this.priorities = previousPriorities;
133	      this.meta = previousMeta;
134	      this.localAttachments = previousLocalAttachments;
135	      this.uiActionJournals = previousUiActionJournals;
136	      throw error;
137	    }
138	  }
139	
140	  async closeAsync(): Promise<void> {
141	    this.closeCalls += 1;
142	  }
143	}
