 123	function StreamingCaret() {
 124	  const styles = createStyles(useKeatingTheme());
 125	  const opacity = useRef(new Animated.Value(0.25)).current;
 126	  const [reduceMotion, setReduceMotion] = useState(false);
 127	
 128	  useEffect(() => {
 129	    void AccessibilityInfo.isReduceMotionEnabled().then(setReduceMotion);
 130	    const subscription = AccessibilityInfo.addEventListener("reduceMotionChanged", setReduceMotion);
 131	    return () => subscription.remove();
 132	  }, []);
 133	
 134	  useEffect(() => {
 135	    if (reduceMotion) {
 136	      opacity.setValue(1);
 137	      return undefined;
 138	    }
 139	    const loop = Animated.loop(
 140	      Animated.sequence([
 141	        Animated.timing(opacity, { toValue: 1, duration: 520, useNativeDriver: true }),
 142	        Animated.timing(opacity, { toValue: 0.25, duration: 520, useNativeDriver: true }),
 143	      ]),
 144	    );
 145	    loop.start();
 146	    return () => loop.stop();
 147	  }, [opacity, reduceMotion]);
 148	
 149	  return <Animated.View accessibilityLabel="Keating is responding" style={[styles.caret, { opacity }]} />;
 150	}
