 24	class FakeDatabase implements AsyncSqlDatabase {
 25	  readonly calls: string[] = [];
 26	  readonly meta = new Map<string, string>();
 27	  readonly journal = new Map<string, JournalRow>();
 28	  exclusiveTransactions = 0;
 29	  closeCalls = 0;
 30	  failOn: string | undefined;
 31	  crossConnectionMigrationInsert: ((row: JournalRow) => void) | undefined;
 32	  migrationInsertFailures: Error[] = [];
 33	  beforeMigrationUpdate: ((row: JournalRow) => void) | undefined;
 34	  private transactionTail: Promise<void> = Promise.resolve();
 35	
 36	  async execAsync(source: string): Promise<void> {
 37	    this.calls.push(`exec:${source}`);
 38	    if (this.failOn && source.includes(this.failOn)) throw new Error("injected open failure");
 39	  }
 40	
 41	  async runAsync(source: string, ...params: SqlBindValue[]): Promise<{ changes: number; lastInsertRowId: number }> {
 42	    this.calls.push(`run:${source}`);
 43	    if (source.startsWith("INSERT INTO repository_meta")) {
 44	      this.meta.set(String(params[0]), String(params[1]));
 45	    } else if (source.startsWith("UPDATE repository_meta")) {
 46	      this.meta.set(String(params[1]), String(params[0]));
 47	    } else if (source.startsWith("INSERT INTO migration_journal")) {
 48	      const [id, sourceVersion, targetVersion, digest, phase, createdAt, updatedAt, completedAt] = params;
 49	      const row = {
 50	        id: String(id), source_version: Number(sourceVersion), target_version: Number(targetVersion),
 51	        digest: String(digest), phase: String(phase), created_at: String(createdAt),
 52	        updated_at: String(updatedAt), completed_at: completedAt === null ? null : String(completedAt),
 53	      };
 54	      const crossConnectionInsert = this.crossConnectionMigrationInsert;
 55	      this.crossConnectionMigrationInsert = undefined;
 56	      crossConnectionInsert?.(row);
 57	      const failure = this.migrationInsertFailures.shift();
 58	      if (failure) throw failure;
 59	      if (this.journal.has(row.id)) {
 60	        throw new Error("UNIQUE constraint failed: migration_journal.id");
 61	      }
 62	      this.journal.set(String(id), row);
 63	    } else if (source.startsWith("UPDATE migration_journal")) {
 64	      const [phase, updatedAt, completedAt, id, expectedPhase] = params;
 65	      const row = this.journal.get(String(id));
 66	      if (!row) throw new Error("missing journal row");
 67	      this.beforeMigrationUpdate?.(row);
 68	      if (row.phase !== String(expectedPhase)) return { changes: 0, lastInsertRowId: 0 };
 69	      row.phase = String(phase);
 70	      row.updated_at = String(updatedAt);
 71	      row.completed_at = completedAt === null ? null : String(completedAt);
 72	    }
 73	    return { changes: 1, lastInsertRowId: 1 };
 74	  }
 75	
 76	  async getFirstAsync<T>(source: string, ...params: SqlBindValue[]): Promise<T | null> {
 77	    return this.getFirstFromJournal(source, params, this.journal);
 78	  }
 79	
 80	  async getAllAsync<T>(_source: string, ..._params: SqlBindValue[]): Promise<T[]> {
 81	    return [];
 82	  }
 83	
 84	  private async getFirstFromJournal<T>(
 85	    source: string,
 86	    params: SqlBindValue[],
 87	    journal: ReadonlyMap<string, JournalRow>,
 88	  ): Promise<T | null> {
 89	    this.calls.push(`get:${source}`);
 90	    if (source.includes("FROM repository_meta")) {
 91	      const value = this.meta.get(String(params[0]));
 92	      return value === undefined ? null : { value } as T;
 93	    }
 94	    if (source.includes("FROM migration_journal")) {
 95	      const row = journal.get(String(params[0]));
 96	      return row ? { ...row } as T : null;
 97	    }
 98	    return null;
 99	  }
100	
101	  async withExclusiveTransactionAsync(task: (transaction: AsyncSqlExecutor) => Promise<void>): Promise<void> {
102	    this.exclusiveTransactions += 1;
103	    const previous = this.transactionTail;
104	    let release!: () => void;
105	    this.transactionTail = new Promise<void>((resolve) => {
106	      release = resolve;
107	    });
108	    await previous;
109	    const journalSnapshot = new Map(
110	      [...this.journal].map(([id, row]) => [id, { ...row }]),
111	    );
112	    const transaction: AsyncSqlExecutor = {
113	      execAsync: (source) => this.execAsync(source),
114	      runAsync: (source, ...params) => this.runAsync(source, ...params),
115	      getFirstAsync: <T>(source: string, ...params: SqlBindValue[]) =>
116	        this.getFirstFromJournal<T>(source, params, journalSnapshot),
117	      getAllAsync: <T>(_source: string, ..._params: SqlBindValue[]) => Promise.resolve([] as T[]),
118	    };
119	    try {
120	      await task(transaction);
121	    } finally {
122	      release();
123	    }
124	  }
125	
126	  async closeAsync(): Promise<void> {
127	    this.closeCalls += 1;
128	  }
129	}
