 33	export function UiDocumentRenderer({
 34	  sourceDocument,
 35	  sessionId,
 36	  onLearnerTurn,
 37	}: {
 38	  sourceDocument: UiDocument;
 39	  sessionId?: string;
 40	  onLearnerTurn: (text: string) => Promise<void>;
 41	}) {
 42	  const theme = useKeatingTheme();
 43	  const styles = createStyles(theme);
 44	  const { dispatchUiAction, getUiActionJournal } = useKeating();
 45	  const [document, setDocument] = useState(sourceDocument);
 46	  const [durableActions, setDurableActions] = useState<UiAction[]>([]);
 47	  const [busy, setBusy] = useState<string | null>(null);
 48	  const [notice, setNotice] = useState<string | null>(null);
 49	  const [error, setError] = useState<string | null>(null);
 50	
 51	  useEffect(() => {
 52	    let active = true;
 53	    setDocument(sourceDocument);
 54	    setDurableActions([]);
 55	    void getUiActionJournal(sourceDocument.id).then((journal) => {
 56	      if (!active) return;
 57	      setDocument(latestUiDocument(journal, sourceDocument));
 58	      setDurableActions(completedUiActions(journal));
 59	    }).catch((cause) => {
 60	      if (active) setError(cause instanceof Error ? cause.message : "Could not restore this interaction.");
 61	    });
 62	    return () => { active = false; };
 63	  }, [getUiActionJournal, sourceDocument]);
 64	
 65	  const run = async (action: UiAction, learnerTurn = true) => {
 66	    if (busy) return false;
 67	    setBusy(action.idempotencyKey);
 68	    setError(null);
 69	    setNotice(null);
 70	    try {
 71	      const result = await dispatchUiAction(action, document, sessionId);
 72	      if (result.resultingDocument) setDocument(result.resultingDocument);
 73	      if (result.status === "completed") {
 74	        setDurableActions((current) => current.some((candidate) => candidate.idempotencyKey === action.idempotencyKey)
 75	          ? current
 76	          : [...current, action]);
 77	      }
 78	      setNotice(result.message ?? "Saved.");
 79	      const response = learnerTurn ? uiActionLearnerMessage(action, document) : null;
 80	      if (response) {
 81	        try {
 82	          await onLearnerTurn(response);
 83	        } catch (cause) {
 84	          setError(cause instanceof Error
 85	            ? `Your progress is saved, but Keating could not respond: ${cause.message}`
 86	            : "Your progress is saved, but Keating could not respond.");
 87	        }
 88	      }
 89	      return true;
 90	    } catch (cause) {
 91	      setError(cause instanceof Error ? cause.message : "Could not save this interaction. Your input is still here; try again.");
 92	      return false;
 93	    } finally {
 94	      setBusy(null);
 95	    }
 96	  };
 97	
 98	  const canInteract = document.lifecycle === "ready" && document.supportedSurfaces.includes("mobile");
 99	  const retryable = document.lifecycle === "failed" || document.lifecycle === "cancelled";
100	  const retryKey = actionKey(document, "retry", document.id, document.lifecycle);
101	  const retryAction: UiAction = {
102	    schemaVersion: UI_CONTRACT_VERSION,
103	    type: "retry",
104	    documentId: document.id,
105	    documentRevision: document.revision,
106	    idempotencyKey: retryKey,
107	  };
108	  return (
109	    <View style={styles.document} accessibilityLabel={`Interactive lesson ${document.id}`}>
110	      <View style={styles.documentHeader}>
111	        <View style={styles.documentTitleRow}>
112	          <Ionicons name="sparkles-outline" size={16} color={theme.colors.primaryText} />
113	          <Text style={styles.documentTitle}>Interactive lesson</Text>
114	        </View>
115	        <Text style={styles.lifecycle}>{document.lifecycle.replace("_", " ")}</Text>
116	      </View>
117	      {retryable ? <View style={styles.recovery}>
118	        <Text style={styles.body}>This interaction stopped before it finished. Your saved work is still here.</Text>
119	        <Button compact loading={busy === retryKey} disabled={busy !== null} onPress={() => void run(retryAction, false)}>Try interaction again</Button>
120	      </View> : null}
121	      {document.nodes.map((node) => (
122	        <UiNode
123	          key={node.id}
124	          node={node}
125	          document={document}
126	          disabled={!canInteract || busy !== null}
127	          busy={busy}
128	          durableActions={durableActions}
129	          run={run}
130	        />
131	      ))}
132	      {notice ? <Text accessibilityLiveRegion="polite" style={styles.notice}>{notice}</Text> : null}
133	      {error ? <Text accessibilityRole="alert" style={styles.error}>{error}</Text> : null}
134	    </View>
135	  );
136	}
