 62	/** Pure semantic adapter used inside UiActionStore's exclusive transaction. */
 63	export function applyLocalUiAction(
 64	  current: PortableLearnerData,
 65	  action: UiAction,
 66	  document: UiDocument,
 67	  now: string,
 68	  sessionId?: string,
 69	): UiActionMutationResult {
 70	  if (action.type === "submit-answer" || action.type === "choose-option") {
 71	    const target = actionTarget(document, action.nodeId);
 72	    const answer = answerText(action, document);
 73	    const check = {
 74	      id: stableId("ui-answer", document.id, action.idempotencyKey),
 75	      topic: target.node.type === "quiz" ? target.node.title : "Interactive check",
 76	      question: target.questionPrompt ?? "OpenUI question",
 77	      answer,
 78	      createdAt: now,
 79	      grading: "pending" as const,
 80	      ...(sessionId ? { sessionId } : {}),
 81	    };
 82	    const next = current.questionChecks.some((candidate) => candidate.id === check.id)
 83	      ? current
 84	      : { ...current, questionChecks: [...current.questionChecks, check] };
 85	    return {
 86	      data: next,
 87	      resultingDocument: nextDocument(document, now, undefined, target.node.type === "question" ? "completed" : "ready"),
 88	      message: "Answer saved on this device.",
 89	    };
 90	  }
 91	
 92	  if (action.type === "complete-goal-step") {
 93	    const target = actionTarget(document, action.nodeId);
 94	    if (target.node.type !== "goal") throw new Error("Goal action target is invalid.");
 95	    const goalId = stableId("ui-goal", document.id, target.node.id);
 96	    const existing = current.goals.find((goal) => goal.id === goalId);
 97	    const baseGoal = existing ?? {
 98	      id: goalId,
 99	      title: target.node.title,
100	      description: target.node.description ?? "",
101	      updatedAt: now,
102	      steps: target.node.steps.map((step) => ({
103	        id: stableId("ui-step", document.id, target.node.id, step.id),
104	        title: step.title,
105	        status: step.status,
106	        successCriteria: [...(step.successCriteria ?? [])],
107	      })),
108	    };
109	    const stepIndex = target.node.steps.findIndex((step) => step.id === action.stepId);
110	    if (stepIndex < 0) throw new Error("Goal step is missing.");
111	    const portableStepId = stableId("ui-step", document.id, target.node.id, action.stepId);
112	    const goal = {
113	      ...baseGoal,
114	      updatedAt: now,
115	      steps: baseGoal.steps.map((step) => step.id === portableStepId ? { ...step, status: "done" as const } : step),
116	    };
117	    const goals = existing
118	      ? current.goals.map((candidate) => candidate.id === goal.id ? goal : candidate)
119	      : [...current.goals, goal];
120	    const resultingDocument = nextDocument(document, now, (nodes) => nodes.map((node) => {
121	      if (node.type !== "goal" || node.id !== target.node.id) return node;
122	      const steps = node.steps.map((step) => step.id === action.stepId ? { ...step, status: "done" as const } : step);
123	      return { ...node, status: steps.every((step) => step.status === "done") ? "completed" as const : node.status, steps };
124	    }), goal.steps.every((step) => step.status === "done") ? "completed" : "ready");
125	    return { data: { ...current, goals }, resultingDocument, message: "Goal progress saved." };
126	  }
127	
128	  if (action.type === "rate-card") {
129	    const target = actionTarget(document, action.nodeId);
130	    if (target.node.type !== "deck") throw new Error("Deck action target is invalid.");
131	    const deckId = stableId("ui-deck", document.id, target.node.id);
132	    const cards = target.node.cards.map((card) => ({
133	      id: stableId("ui-card", document.id, target.node.id, card.id),
134	      front: card.front,
135	      back: card.back,
136	      tags: [...(card.tags ?? [])],
137	    }));
138	    const withDeck = current.decks.some((deck) => deck.id === deckId)
139	      ? current
140	      : createDeckWithCards(current, { id: deckId, title: target.node.title, topic: target.node.topic, createdAt: now, cards });
141	    const cardId = stableId("ui-card", document.id, target.node.id, action.cardId);
142	    const reviewed = recordCardReview(
143	      withDeck,
144	      deckId,
145	      cardId,
146	      action.rating,
147	      stableId("ui-review", document.id, action.idempotencyKey),
148	      now,
149	      sessionId,
150	    );
151	    return {
152	      data: reviewed.data,
153	      resultingDocument: nextDocument(document, now),
154	      message: "Card rating saved and the review schedule was updated.",
155	    };
156	  }
157	
158	  if (action.type === "save-artifact") {
159	    const target = actionTarget(document, action.nodeId);
160	    if (!(target.node.type === "study-plan" || target.node.type === "artifact"
161	      || target.node.type === "image" || target.node.type === "media")) {
162	      throw new Error("Artifact action target is invalid.");
163	    }
164	    const resource = target.node.resource;
165	    const id = stableId("ui-artifact", document.id, target.node.id);
166	    const kind = target.node.type === "study-plan" ? "study-plan" as const
167	      : target.node.type === "image" ? "image" as const
168	        : target.node.type === "media" && target.node.kind === "animation" ? "animation" as const
169	          : target.node.type === "media" ? "document" as const : "other" as const;
170	    const format = resource.format === "markdown" ? "markdown" as const
171	      : target.node.type === "image" ? "image" as const
172	        : target.node.type === "media" && target.node.kind === "video" ? "video" as const
173	          : resource.format === "json" ? "json" as const : "text" as const;
174	    const artifact = {
175	      id,
176	      kind,
177	      format,
178	      title: resource.title,
179	      createdAt: now,
180	      updatedAt: now,
181	      content: resource.content ?? resource.uri ?? "",
182	      ...(sessionId ? { sourceSessionId: sessionId } : {}),
183	    };
184	    return {
185	      data: current.artifacts.some((candidate) => candidate.id === id)
186	        ? current
187	        : { ...current, artifacts: [...current.artifacts, artifact] },
188	      resultingDocument: nextDocument(document, now, undefined, "completed"),
189	      message: "Artifact saved to your library.",
190	    };
191	  }
192	
193	  if (action.type === "retry") {
194	    return { data: current, resultingDocument: nextDocument(document, now), message: "Interaction is ready to try again." };
195	  }
196	
197	  return {
198	    data: current,
199	    resultingDocument: nextDocument(document, now, undefined, "completed"),
200	    message: "Handoff opened.",
201	  };
202	}
