204	export function uiActionLearnerMessage(action: UiAction, document: UiDocument): string | null {
205	  if (action.type === "submit-answer" || action.type === "choose-option") {
206	    const target = actionTarget(document, action.nodeId);
207	    return `My answer to "${target.questionPrompt ?? "the check"}": ${answerText(action, document)}`;
208	  }
209	  if (action.type === "complete-goal-step") {
210	    const target = actionTarget(document, action.nodeId);
211	    const step = target.node.type === "goal" ? target.node.steps.find((candidate) => candidate.id === action.stepId) : undefined;
212	    return step ? `I completed the goal step: ${step.title}. What should I do next?` : null;
213	  }
214	  return null;
215	}
