 27	export function markdownTokenTypes(tokens: readonly Token[]): string[] {
 28	  const types: string[] = [];
 29	  const visit = (entries: readonly Token[]) => {
 30	    for (const token of entries) {
 31	      types.push(token.type);
 32	      if ("tokens" in token && Array.isArray(token.tokens)) visit(token.tokens);
 33	      if (token.type === "list") (token as Tokens.List).items.forEach((item: Tokens.ListItem) => visit(item.tokens));
 34	      if (token.type === "table") {
 35	        (token as Tokens.Table).header.forEach((cell: Tokens.TableCell) => visit(cell.tokens));
 36	        (token as Tokens.Table).rows.flat().forEach((cell: Tokens.TableCell) => visit(cell.tokens));
 37	      }
 38	      if (token.type === "blockquote") visit((token as Tokens.Blockquote).tokens);
 39	    }
 40	  };
 41	  visit(tokens);
 42	  return types;
 43	}
