  9	const OPENING_FENCE = /^```(?:keating-ui|ui-document|openui-json|openui)(?:[ \t]+[^\n]*)?\n/gm;
 10	const MAX_DOCUMENTS = 8;
 11	
 12	/**
 13	 * Compiles the JSON interchange form of Keating OpenUI into validated shared
 14	 * documents. Browser OpenUI source is never evaluated on-device.
 15	 */
 16	export function extractUiDocuments(source: string): ExtractedUiDocuments {
 17	  const documents: UiDocument[] = [];
 18	  const errors: string[] = [];
 19	  const text: string[] = [];
 20	  let cursor = 0;
 21	  OPENING_FENCE.lastIndex = 0;
 22	  let match: RegExpExecArray | null;
 23	  while ((match = OPENING_FENCE.exec(source)) !== null) {
 24	    const bodyStart = OPENING_FENCE.lastIndex;
 25	    const closingMatch = /^```[ \t]*$/m.exec(source.slice(bodyStart));
 26	    if (!closingMatch) break;
 27	    const bodyEnd = bodyStart + closingMatch.index;
 28	    const fenceEnd = bodyEnd + closingMatch[0].length;
 29	    const body = source.slice(bodyStart, bodyEnd).trim();
 30	    text.push(source.slice(cursor, match.index));
 31	    if (documents.length >= MAX_DOCUMENTS) {
 32	      errors.push("This response contains more interactive documents than mobile can safely render.");
 33	    } else {
 34	      try {
 35	        const candidate = JSON.parse(body) as unknown;
 36	        if (!validateUiDocument(candidate)) throw new Error("document schema is invalid");
 37	        if (!candidate.supportedSurfaces.includes("mobile")) {
 38	          errors.push(`Interactive document ${candidate.id} does not declare mobile support.`);
 39	        } else {
 40	          documents.push(candidate);
 41	        }
 42	      } catch (error) {
 43	        errors.push(error instanceof Error
 44	          ? `Interactive document could not be rendered: ${error.message}.`
 45	          : "Interactive document could not be rendered.");
 46	      }
 47	    }
 48	    cursor = fenceEnd;
 49	    if (source[cursor] === "\n") cursor += 1;
 50	    OPENING_FENCE.lastIndex = cursor;
 51	  }
 52	  text.push(source.slice(cursor));
 53	  return { content: text.join("").trim(), documents, errors };
 54	}
