 56	/** Prevent partially streamed JSON from flashing as a code block. */
 57	export function hideUnclosedUiDocumentFence(source: string): string {
 58	  OPENING_FENCE.lastIndex = 0;
 59	  let match: RegExpExecArray | null;
 60	  let lastUnclosed = -1;
 61	  while ((match = OPENING_FENCE.exec(source)) !== null) {
 62	    const closing = /^```[ \t]*$/m.exec(source.slice(OPENING_FENCE.lastIndex));
 63	    if (!closing) {
 64	      lastUnclosed = match.index;
 65	      break;
 66	    }
 67	    OPENING_FENCE.lastIndex += closing.index + closing[0].length;
 68	  }
 69	  return lastUnclosed < 0 ? source : source.slice(0, lastUnclosed).trimEnd();
 70	}
