 20	function hash(value: string): string {
 21	  let result = 2166136261;
 22	  for (let index = 0; index < value.length; index += 1) {
 23	    result ^= value.charCodeAt(index);
 24	    result = Math.imul(result, 16777619);
 25	  }
 26	  return (result >>> 0).toString(36);
 27	}
