 11	function shortHash(value: string): string {
 12	  let hash = 2166136261;
 13	  for (let index = 0; index < value.length; index += 1) {
 14	    hash ^= value.charCodeAt(index);
 15	    hash = Math.imul(hash, 16777619);
 16	  }
 17	  return (hash >>> 0).toString(36);
 18	}
