 24	function actionTarget(document: UiDocument, nodeId: string): { node: UiDocumentNode; questionPrompt?: string } {
 25	  for (const node of document.nodes) {
 26	    if (node.id === nodeId) return { node, questionPrompt: node.type === "question" ? node.prompt : undefined };
 27	    if (node.type === "quiz") {
 28	      const question = node.questions.find((candidate) => candidate.id === nodeId);
 29	      if (question) return { node, questionPrompt: question.prompt };
 30	    }
 31	  }
 32	  throw new Error(`OpenUI action target ${nodeId} is missing.`);
 33	}
