 36	  source: UiDocument,
 37	  now: string,
 38	  update: (nodes: UiDocumentNode[]) => UiDocumentNode[] = (nodes) => nodes,
 39	  lifecycle: UiDocument["lifecycle"] = "ready",
 40	): UiDocument {
 41	  return {
 42	    ...source,
 43	    revision: source.revision + 1,
 44	    lifecycle,
 45	    nodes: update(structuredClone(source.nodes)),
 46	    updatedAt: now,
 47	  };
 48	}
