 53	  const question = target.node.type === "question"
 54	    ? target.node
 55	    : target.node.type === "quiz"
 56	      ? target.node.questions.find((candidate) => candidate.id === action.nodeId)
 57	      : undefined;
 58	  const labels = new Map(question?.choices?.map((choice) => [choice.id, choice.label]) ?? []);
 59	  return action.optionIds.map((id) => labels.get(id) ?? id).join(", ");
