 63	export function applyLocalUiAction(
 64	  current: PortableLearnerData,
 65	  action: UiAction,
 66	  document: UiDocument,
 67	  now: string,
 68	  sessionId?: string,
 69	): UiActionMutationResult {
 70	  if (action.type === "submit-answer" || action.type === "choose-option") {
 71	    const target = actionTarget(document, action.nodeId);
 72	    const answer = answerText(action, document);
 73	    const check = {
 74	      id: stableId("ui-answer", document.id, action.idempotencyKey),
 75	      topic: target.node.type === "quiz" ? target.node.title : "Interactive check",
 76	      question: target.questionPrompt ?? "OpenUI question",
 77	      answer,
 78	      createdAt: now,
 79	      grading: "pending" as const,
 80	      ...(sessionId ? { sessionId } : {}),
 81	    };
 82	    const next = current.questionChecks.some((candidate) => candidate.id === check.id)
 83	      ? current
 84	      : { ...current, questionChecks: [...current.questionChecks, check] };
 85	    return {
 86	      data: next,
 87	      // Per-question completion lives in the durable action journal. Keeping
 88	      // the document ready prevents one answer from disabling sibling nodes.
 89	      resultingDocument: nextDocument(document, now),
 90	      message: "Answer saved on this device.",
 91	    };
 92	  }
 93	
 94	  if (action.type === "complete-goal-step") {
 95	    const target = actionTarget(document, action.nodeId);
 96	    if (target.node.type !== "goal") throw new Error("Goal action target is invalid.");
 97	    const goalId = stableId("ui-goal", document.id, target.node.id);
 98	    const existing = current.goals.find((goal) => goal.id === goalId);
 99	    const baseGoal = existing ?? {
100	      id: goalId,
101	      title: target.node.title,
102	      description: target.node.description ?? "",
103	      updatedAt: now,
104	      steps: target.node.steps.map((step) => ({
105	        id: stableId("ui-step", document.id, target.node.id, step.id),
106	        title: step.title,
107	        status: step.status,
108	        successCriteria: [...(step.successCriteria ?? [])],
109	      })),
110	    };
111	    const stepIndex = target.node.steps.findIndex((step) => step.id === action.stepId);
112	    if (stepIndex < 0) throw new Error("Goal step is missing.");
113	    const portableStepId = stableId("ui-step", document.id, target.node.id, action.stepId);
114	    const goal = {
115	      ...baseGoal,
116	      updatedAt: now,
117	      steps: baseGoal.steps.map((step) => step.id === portableStepId ? { ...step, status: "done" as const } : step),
118	    };
119	    const goals = existing
120	      ? current.goals.map((candidate) => candidate.id === goal.id ? goal : candidate)
121	      : [...current.goals, goal];
122	    const resultingDocument = nextDocument(document, now, (nodes) => nodes.map((node) => {
123	      if (node.type !== "goal" || node.id !== target.node.id) return node;
124	      const steps = node.steps.map((step) => step.id === action.stepId ? { ...step, status: "done" as const } : step);
125	      return { ...node, status: steps.every((step) => step.status === "done") ? "completed" as const : node.status, steps };
126	    }));
127	    return { data: { ...current, goals }, resultingDocument, message: "Goal progress saved." };
128	  }
129	
130	  if (action.type === "rate-card") {
131	    const target = actionTarget(document, action.nodeId);
132	    if (target.node.type !== "deck") throw new Error("Deck action target is invalid.");
133	    const deckId = stableId("ui-deck", document.id, target.node.id);
134	    const cards = target.node.cards.map((card) => ({
135	      id: stableId("ui-card", document.id, target.node.id, card.id),
136	      front: card.front,
137	      back: card.back,
138	      tags: [...(card.tags ?? [])],
139	    }));
140	    const withDeck = current.decks.some((deck) => deck.id === deckId)
141	      ? current
142	      : createDeckWithCards(current, { id: deckId, title: target.node.title, topic: target.node.topic, createdAt: now, cards });
143	    const cardId = stableId("ui-card", document.id, target.node.id, action.cardId);
144	    const reviewed = recordCardReview(
145	      withDeck,
146	      deckId,
147	      cardId,
148	      action.rating,
149	      stableId("ui-review", document.id, action.idempotencyKey),
150	      now,
151	      sessionId,
152	    );
153	    return {
154	      data: reviewed.data,
155	      resultingDocument: nextDocument(document, now),
156	      message: "Card rating saved and the review schedule was updated.",
157	    };
158	  }
159	
160	  if (action.type === "save-artifact") {
161	    const target = actionTarget(document, action.nodeId);
162	    if (!(target.node.type === "study-plan" || target.node.type === "artifact"
163	      || target.node.type === "image" || target.node.type === "media")) {
164	      throw new Error("Artifact action target is invalid.");
165	    }
166	    const resource = target.node.resource;
167	    const id = stableId("ui-artifact", document.id, target.node.id);
168	    const kind = target.node.type === "study-plan" ? "study-plan" as const
169	      : target.node.type === "image" ? "image" as const
170	        : target.node.type === "media" && target.node.kind === "animation" ? "animation" as const
171	          : target.node.type === "media" ? "document" as const : "other" as const;
172	    const format = resource.format === "markdown" ? "markdown" as const
173	      : target.node.type === "image" ? "image" as const
174	        : target.node.type === "media" && target.node.kind === "video" ? "video" as const
175	          : resource.format === "json" ? "json" as const : "text" as const;
176	    const artifact = {
177	      id,
178	      kind,
179	      format,
180	      title: resource.title,
181	      createdAt: now,
182	      updatedAt: now,
183	      content: resource.content ?? resource.uri ?? "",
