207	export function uiActionLearnerMessage(action: UiAction, document: UiDocument): string | null {
208	  if (action.type === "submit-answer" || action.type === "choose-option") {
209	    const target = actionTarget(document, action.nodeId);
210	    return `My answer to "${target.questionPrompt ?? "the check"}": ${answerText(action, document)}`;
211	  }
212	  if (action.type === "complete-goal-step") {
213	    const target = actionTarget(document, action.nodeId);
214	    const step = target.node.type === "goal" ? target.node.steps.find((candidate) => candidate.id === action.stepId) : undefined;
215	    return step ? `I completed the goal step: ${step.title}. What should I do next?` : null;
216	  }
217	  return null;
218	}
