  3	/** Return the newest durable document snapshot produced by a completed action. */
  4	export function latestUiDocument(
  5	  journal: UiActionJournal,
  6	  source: UiDocument,
  7	): UiDocument {
  8	  const latest = [...journal.receipts]
  9	    .reverse()
 10	    .find((receipt) => receipt.state === "completed" && receipt.result?.resultingDocument)
 11	    ?.result?.resultingDocument;
 12	  return latest && latest.revision >= source.revision ? latest : source;
 13	}
