 9	const OPENING_FENCE = /^```(?:keating-ui|ui-document|openui-json|openui)(?:[ \t]+[^\n]*)?\n/gm;
10	const MAX_DOCUMENTS = 8;
11	
12	function scopeHash(value: string, seed: number): string {
13	  let result = seed >>> 0;
14	  for (let index = 0; index < value.length; index += 1) {
15	    result ^= value.charCodeAt(index);
16	    result = Math.imul(result, 16777619);
17	  }
18	  return (result >>> 0).toString(36);
19	}
