21	/** Namespace a model-authored ID to the persisted session/message event. */
22	export function scopeUiDocument(document: UiDocument, scope: string): UiDocument {
23	  if (!scope.trim()) throw new Error("OpenUI document scope is required.");
24	  const suffix = `${scopeHash(scope, 2166136261)}${scopeHash([...scope].reverse().join(""), 2246822519)}`;
25	  return { ...structuredClone(document), id: `${document.id.slice(0, 96)}--${suffix}` };
26	}
