28	/**
29	 * Compiles the JSON interchange form of Keating OpenUI into validated shared
30	 * documents. Browser OpenUI source is never evaluated on-device.
31	 */
32	export function extractUiDocuments(source: string): ExtractedUiDocuments {
33	  const documents: UiDocument[] = [];
34	  const errors: string[] = [];
35	  const text: string[] = [];
36	  let cursor = 0;
37	  OPENING_FENCE.lastIndex = 0;
38	  let match: RegExpExecArray | null;
39	  while ((match = OPENING_FENCE.exec(source)) !== null) {
40	    const bodyStart = OPENING_FENCE.lastIndex;
41	    const closingMatch = /^```[ \t]*$/m.exec(source.slice(bodyStart));
42	    if (!closingMatch) break;
43	    const bodyEnd = bodyStart + closingMatch.index;
44	    const fenceEnd = bodyEnd + closingMatch[0].length;
45	    const body = source.slice(bodyStart, bodyEnd).trim();
46	    text.push(source.slice(cursor, match.index));
47	    if (documents.length >= MAX_DOCUMENTS) {
48	      errors.push("This response contains more interactive documents than mobile can safely render.");
49	    } else {
50	      try {
51	        const candidate = JSON.parse(body) as unknown;
52	        if (!validateUiDocument(candidate)) throw new Error("document schema is invalid");
53	        if (!candidate.supportedSurfaces.includes("mobile")) {
54	          errors.push(`Interactive document ${candidate.id} does not declare mobile support.`);
55	        } else {
56	          documents.push(candidate);
57	        }
58	      } catch (error) {
59	        errors.push(error instanceof Error
60	          ? `Interactive document could not be rendered: ${error.message}.`
61	          : "Interactive document could not be rendered.");
62	      }
63	    }
64	    cursor = fenceEnd;
65	    if (source[cursor] === "\n") cursor += 1;
66	    OPENING_FENCE.lastIndex = cursor;
67	  }
68	  text.push(source.slice(cursor));
69	  return { content: text.join("").trim(), documents, errors };
70	}
71	
72	/** Prevent partially streamed JSON from flashing as a code block. */
73	export function hideUnclosedUiDocumentFence(source: string): string {
74	  OPENING_FENCE.lastIndex = 0;
75	  let match: RegExpExecArray | null;
76	  let lastUnclosed = -1;
77	  while ((match = OPENING_FENCE.exec(source)) !== null) {
78	    const closing = /^```[ \t]*$/m.exec(source.slice(OPENING_FENCE.lastIndex));
79	    if (!closing) {
80	      lastUnclosed = match.index;
81	      break;
82	    }
83	    OPENING_FENCE.lastIndex += closing.index + closing[0].length;
84	  }
85	  return lastUnclosed < 0 ? source : source.slice(0, lastUnclosed).trimEnd();
86	}
