    18	/** A bounded native renderer for the flowcharts Keating emits most often. */
    19	export function parseMermaidFlowchart(source: string): MermaidFlowchart | null {
    20	  if (source.length > 16_384) return null;
    21	  const statements = source.split(/[;\n]+/).map((line) => line.trim()).filter(Boolean);
    22	  const header = statements.shift()?.match(/^(?:graph|flowchart)\s+(TD|TB|LR|RL)$/i);
    23	  if (!header) return null;
    24	  const direction = header[1]!.toUpperCase() === "TB" ? "TD" : header[1]!.toUpperCase() as MermaidFlowchart["direction"];
    25	  const labels = new Map<string, string>();
    26	  const edges: MermaidEdge[] = [];
    27	  const addNode = (id: string, ...possible: Array<string | undefined>) => labels.set(id, possible.map(cleanLabel).find(Boolean) ?? labels.get(id) ?? id);
    28	  for (const statement of statements) {
    29	    // Native uses the Keating theme, so safe visual-only directives are ignored.
    30	    if (/^(?:classDef|class|style|linkStyle)\b/i.test(statement)) continue;
    31	    // Grouping is flattened while retaining its nodes and edges.
    32	    if (/^(?:subgraph\b|end$|direction\b|accTitle\s*:|accDescr\s*:|title\s+)/i.test(statement)) continue;
    33	    // Mermaid click callbacks and URLs are executable navigation and never run natively.
    34	    if (/^click\b/i.test(statement)) return null;
    35	    const edge = statement.match(EDGE);
    36	    if (edge) {
    37	      const [from, fromBox, fromCircle, fromRound, fromDiamond, edgeLabel, to, toBox, toCircle, toRound, toDiamond] = edge.slice(1);
    38	      addNode(from!, fromBox, fromCircle, fromRound, fromDiamond);
    39	      addNode(to!, toBox, toCircle, toRound, toDiamond);
    40	      edges.push({ from: from!, to: to!, ...(edgeLabel?.trim() ? { label: edgeLabel.trim() } : {}) });
    41	      continue;
    42	    }
    43	    const declaration = statement.match(DECLARATION);
    44	    if (!declaration) return null;
    45	    addNode(declaration[1]!, declaration[2], declaration[3], declaration[4], declaration[5]);
    46	  }
    47	  if (!labels.size || labels.size > 48 || edges.length > 96) return null;
    48	  const levels = new Map([...labels.keys()].map((id) => [id, 0]));
    49	  for (let pass = 0; pass < labels.size; pass += 1) {
    50	    let changed = false;
    51	    for (const edge of edges) {
